+// API keys, roles and the audit log. Keys live in `apiKeys` as
+// { key, name, role }; roles are viewer < cook < manager. Audit entries
+// record who changed (or tried to change) data: { id, at, keyName, method,
+// path, status }. Both collections may be missing in older files.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for a presented key, or null if there is none. */
+export function findKey(store, presented) {
+  if (typeof presented !== "string" || presented === "") return null;
+  const wanted = digest(presented);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key === "string" && k.key !== "" && timingSafeEqual(digest(k.key), wanted)) found ??= k;
+  }
+  return found;
+}
+
+/** Appends an audit entry; returns it. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.id - a.id);
+}
