+// Who may call which route. `viewer` may only read (GET); `cook` may also
+// cook, record waste, log temperatures and enter stock-take counts;
+// `manager` may do everything. Some reads are for managers only.
+
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+const MANAGER_READS = new Set(["GET /audit"]);
+
+/** The Bearer key in an Authorization header, or null. */
+export function bearerKey(headers = {}) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const value = name === undefined ? undefined : headers[name];
+  const m = typeof value === "string" ? /^Bearer\s+(\S+)\s*$/i.exec(value) : null;
+  return m ? m[1] : null;
+}
+
+/** Whether `role` may call the route `method pattern`. */
+export function allowed(role, method, pattern) {
+  if (role === "manager") return true;
+  const route = `${method} ${pattern}`;
+  if (method === "GET" && !MANAGER_READS.has(route)) return role === "viewer" || role === "cook";
+  return role === "cook" && COOK_ROUTES.has(route);
+}
