+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, auth, NOW } from "./helpers.js";
+
+test("no key or an unknown key is 401 in the error shape", async () => {
+  const { handle, store } = app();
+  const none = await handle({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  assert.equal(typeof none.body.error.message, "string");
+  const wrong = await handle({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(wrong.status, 401);
+  const notBearer = await handle({ path: "/items", headers: { authorization: "seed-manager-key" } });
+  assert.equal(notBearer.status, 401);
+  const post = await handle({ method: "POST", path: "/jobs/nightly" });
+  assert.equal(post.status, 401);
+  assert.equal(store.data.outbox.length, 0);
+  assert.equal(store.data.audit.length, 0);
+});
+
+test("the header name is case-insensitive", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { Authorization: "Bearer seed-viewer-key" } });
+  assert.equal(res.status, 200);
+});
+
+test("a viewer may only read", async () => {
+  const { handle, store } = app();
+  assert.equal((await handle({ headers: auth("viewer"), path: "/items" })).status, 200);
+  assert.equal((await handle({ headers: auth("viewer"), path: "/reports/stock-value" })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const cook = await handle({ headers: auth("viewer"), method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(cook.status, 403);
+  assert.equal(cook.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal((await handle({ headers: auth("viewer"), path: "/audit" })).status, 403);
+});
+
+test("a cook may cook, waste, log temperatures and count, nothing else", async () => {
+  const { handle } = app();
+  const as = (method, path, body) => handle({ headers: auth("cook"), method, path, body });
+  assert.equal((await as("POST", "/recipes/1/cook", { portions: 1 })).status, 200);
+  assert.equal((await as("POST", "/batches/6/waste", { qty: 0.5, reason: "spill" })).status, 201);
+  assert.equal((await as("POST", "/temperatures", { location: "fridge", celsius: 3 })).status, 201);
+  assert.equal((await as("POST", "/stocktakes", { location: "dry" })).status, 403);
+  const take = (await handle({ headers: auth(), method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await as("POST", `/stocktakes/${take.id}/counts`, { batchId: 6, counted: 12 })).status, 200);
+  assert.equal((await as("POST", `/stocktakes/${take.id}/finish`)).status, 403);
+  assert.equal((await as("POST", "/orders", { supplierId: 1, lines: [{ itemId: 4, qty: 1 }] })).status, 403);
+  assert.equal((await as("PUT", "/items/1/allergens", { allergens: ["milk"] })).status, 403);
+  assert.equal((await as("POST", "/jobs/nightly")).status, 403);
+  assert.equal((await as("GET", "/items")).status, 200);
+  assert.equal((await as("GET", "/audit")).status, 403);
+});
+
+test("changes are audited and managers read the audit newest first", async () => {
+  const { handle, store } = app();
+  await handle({ headers: auth("cook"), method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } });
+  await handle({ headers: auth("viewer"), method: "POST", path: "/jobs/nightly" });
+  await handle({ headers: auth(), method: "POST", path: "/recipes/2/cook", body: { portions: 100 } });
+  await handle({ headers: auth(), path: "/items" });
+  assert.equal(store.data.audit.length, 3);
+  const res = await handle({ headers: auth(), path: "/audit" });
+  assert.equal(res.status, 200);
+  const at = new Date(NOW).toISOString();
+  assert.deepEqual(res.body.map(({ id, ...e }) => e), [
+    { at, keyName: "kitchen manager", method: "POST", path: "/recipes/2/cook", status: 409 },
+    { at, keyName: "front desk", method: "POST", path: "/jobs/nightly", status: 403 },
+    { at, keyName: "line cook", method: "POST", path: "/temperatures", status: 201 },
